ValidationRule.errorConditionFormula:
AND(
    OR(RecordType.DeveloperName = "NewOperationalTest", RecordType.DeveloperName = "OldNewOperationalTest"),
    OR(
        AND(
            ISPICKVAL(StageName__c, "フェーズ11 役員決裁裁可"),
            OR(
                NOT(INCLUDES(CompletionBasis__c, "11-1:①決裁者への説明を完了した。")),
                NOT(INCLUDES(CompletionBasis__c, "11-2:②決裁者から提案内容と見積りに合意をいただいた。")),
                NOT(INCLUDES(CompletionBasis__c, "11-3:③注文書を受け取った。"))
            )
        )
    )
)
